// Источник: web-тест .qa/e2e/tests/profile/pr-01-guest-no-password.spec.ts, план .qa/e2e/specs/profile.md, кейс .qa/tests/profile/PR-01-profile-sections-no-password.md
// Тикет #6a86f7f9. Гость: на экранах номера и регистрации нет входа/регистрации по паролю.
// Шаг 2 web (маршруты /forgot-password и др. → «Unmatched Route») — только при наличии deep link (APP_SCHEME), иначе пропускается.
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, tapLabel, tapText, scrollToText } from '../../helpers/ui.ts';
import { hasDeepLinks, openRoute } from '../../helpers/nav.ts';
import { ensureAppReady, isLoggedIn, toHome } from '../../helpers/app.ts';

/** Выход: профиль → «התנתקות» (+ подтверждение, если есть) → splash. */
async function logout() {
  await toHome();
  await tapLabel('מעבר לפרטים שלי');
  await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
  await (await scrollToText('התנתקות')).click();
  await driver.waitUntil(async () => {
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) return true;
    const confirm = await byText('התנתקות');
    if (await confirm.isDisplayed().catch(() => false)) await confirm.click().catch(() => {});
    return false;
  }, { timeout: 20000, interval: 700, timeoutMsg: 'после «התנתקות» не открылся splash' });
}
/** Вернуться к splash/входу и войти снова (login() начинает со splash или экрана номера). */
async function restoreLogin() {
  for (let i = 0; i < 4; i++) {
    if (await isLoggedIn()) return;
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) break;
    if (await byText('כניסה דרך מספר נייד').isDisplayed().catch(() => false)) break;
    await driver.back();
  }
  await ensureAppReady();
}

async function tapJoin() {
  const t = await byText('הצטרפו אלינו');
  if (await t.isDisplayed().catch(() => false)) return t.click();
  return tapLabel('הצטרפו אלינו');
}
async function expectNoPasswordEntry() {
  await expect(byTextContains('כניסה עם מייל וסיסמה')).not.toBeDisplayed();
  await expect(byTextContains('הרשמה עם מייל וסיסמה')).not.toBeDisplayed();
  await expect(byTextContains('סיסמה')).not.toBeDisplayed();
}

describe('Профиль — гость: нет входа/экранов с паролем', () => {
  before(async () => { await logout(); });
  after(async () => { await restoreLogin(); });

  it('PR-01 Гость: на экранах номера и регистрации нет входа по паролю, экраны пароля не открываются #6a86f7f9 @prod-safe', async function () {
    // 1. Экран номера, затем регистрация — нет ссылок «… עם מייל וסיסמה».
    await tapText('בואו נתחיל');
    await (await byText('כניסה דרך מספר נייד')).waitForDisplayed({ timeout: 20000 });
    await expectNoPasswordEntry();
    await tapJoin();
    await (await byText('יצירת חשבון')).waitForDisplayed({ timeout: 20000 });
    await expectNoPasswordEntry();
    await scrollToText('שלח');
    await expectNoPasswordEntry();

    // 2. Экраны пароля не открываются (deep link).
    if (!hasDeepLinks()) return;
    for (const route of ['/forgot-password', '/change-password', '/reset-password', '/set-password', '/login-email']) {
      await openRoute(route);
      await (await byText('Unmatched Route')).waitForDisplayed({ timeout: 15000 });
      await expect(byText('Page could not be found.')).toBeDisplayed();
      await driver.back();
    }
  });
});
